  /** A folder like metrics/: index.html and test/fixtures/<case>/data/. */
  def tree(page: String = "<!doctype html><title>piabrota metrics</title>"): os.Path =
    val dir = os.temp.dir(prefix = "metrics")
    os.write(dir / "index.html", page)
    for (c, files) <- cases; (name, text) <- files do
      os.write(dir / "test" / "fixtures" / c / "data" / name, text + "\n", createFolders = true)
    dir
